contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        require(_feeRate > 5000, "exercise revert branch");

        bool reverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && !c.initialized());
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint56 changeFee, uint256 inputAmount) public {
        require(changeFee > 0, "nonzero fee");
        require(inputAmount <= type(uint256).max / changeFee, "overflow guard");

        // fresh pool: baseToken() == address(0), so exponent = 18 - 4
        (uint256 feeAmount, uint256 protocolFeeAmount) = c.changeFeeQuote(inputAmount);

        uint256 factoryFeeRate = Factory(c.factory()).protocolFeeRate();
        uint256 expectedFee = (inputAmount * changeFee) / 10000;
        uint256 expectedProtocol = (expectedFee * factoryFeeRate) / 10000;

        assert(feeAmount == expectedFee && protocolFeeAmount == expectedProtocol && c.baseToken() == address(0));
    }

    receive() external payable {}
}

