contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _vb,
        uint128 _vn,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useOracle,
        bool _payRoyalties,
        uint128 vb2,
        uint128 vn2,
        bytes32 mr2,
        uint16 fr2,
        bool uo2,
        bool pr2
    ) public {
        require(_feeRate <= 5_000);

        c.initialize(_baseToken, _nft, _vb, _vn, _changeFee, _feeRate, _merkleRoot, _useOracle, _payRoyalties);

        bool firstNotInit = !c.initialized();
        bool baseOk = (c.baseToken() == _baseToken);
        bool nftOk = (c.nft() == _nft);
        bool feeOk = (c.feeRate() == _feeRate);

        bool reverted;
        try c.setAllParameters(vb2, vn2, mr2, fr2 > 5_000 ? 5_000 : fr2, uo2, pr2) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(!firstNotInit && baseOk && nftOk && feeOk && !reverted && c.initialized());
    }
}

