contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address baseTokenArg,
        address nftArg,
        uint128 virtualBaseTokenReservesArg,
        uint128 virtualNftReservesArg,
        uint56 changeFeeArg,
        uint16 feeRateArg,
        bytes32 merkleRootArg,
        bool useStolenNftOracleArg,
        bool payRoyaltiesArg
    ) public {
        require(feeRateArg <= 5_000);

        c.initialize(
            baseTokenArg,
            nftArg,
            virtualBaseTokenReservesArg,
            virtualNftReservesArg,
            changeFeeArg,
            feeRateArg,
            merkleRootArg,
            useStolenNftOracleArg,
            payRoyaltiesArg
        );

        bool secondReverted;
        try c.initialize(
            baseTokenArg,
            nftArg,
            virtualBaseTokenReservesArg,
            virtualNftReservesArg,
            changeFeeArg,
            feeRateArg,
            merkleRootArg,
            useStolenNftOracleArg,
            payRoyaltiesArg
        ) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(
            secondReverted
                && c.initialized()
                && c.baseToken() == baseTokenArg
                && c.nft() == nftArg
                && c.virtualBaseTokenReserves() == virtualBaseTokenReservesArg
                && c.virtualNftReserves() == virtualNftReservesArg
                && c.changeFee() == changeFeeArg
                && c.feeRate() == feeRateArg
                && c.merkleRoot() == merkleRootArg
                && c.useStolenNftOracle() == useStolenNftOracleArg
                && c.payRoyalties() == payRoyaltiesArg
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address baseTokenArg,
        address nftArg,
        uint128 virtualBaseTokenReservesArg,
        uint128 virtualNftReservesArg,
        uint56 changeFeeArg,
        uint16 feeRateArg,
        bytes32 merkleRootArg,
        bool useStolenNftOracleArg,
        bool payRoyaltiesArg,
        uint256 inputAmount
    ) public {
        require(feeRateArg <= 5_000);
        require(inputAmount > 0 && inputAmount < 1 << 64);
        require(virtualNftReservesArg > inputAmount);
        require(virtualBaseTokenReservesArg < 1 << 120);

        c.initialize(
            baseTokenArg,
            nftArg,
            virtualBaseTokenReservesArg,
            virtualNftReservesArg,
            changeFeeArg,
            feeRateArg,
            merkleRootArg,
            useStolenNftOracleArg,
            payRoyaltiesArg
        );

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) =
            c.buyQuote(inputAmount);

        uint256 expectedInput =
            FixedPointMathLib.mulDivUp(
                inputAmount,
                virtualBaseTokenReservesArg,
                virtualNftReservesArg - inputAmount
            );
        uint256 expectedFee = expectedInput * feeRateArg / 10_000;
        uint256 expectedProtocolFee =
            expectedInput * Factory(c.factory()).protocolFeeRate() / 10_000;

        assert(
            feeAmount == expectedFee
                && protocolFeeAmount == expectedProtocolFee
                && netInputAmount == expectedInput + expectedFee + expectedProtocolFee
        );
    }

    receive() external payable {}
}

