contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint16 feeRateArg,
        uint128 virtualBaseTokenReservesArg,
        uint128 virtualNftReservesArg,
        uint256 inputAmount
    ) public {
        require(feeRateArg <= 5000);
        require(virtualNftReservesArg > 0);
        require(inputAmount > 0 && inputAmount <= type(uint128).max);

        c.initialize(
            address(0),
            address(0),
            virtualBaseTokenReservesArg,
            virtualNftReservesArg,
            0,
            feeRateArg,
            bytes32(0),
            false,
            false
        );

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(inputAmount);

        uint256 expectedOutput = (inputAmount * uint256(virtualBaseTokenReservesArg))
            / (uint256(virtualNftReservesArg) + inputAmount);

        assert(
            feeAmount == (expectedOutput * feeRateArg) / 10_000
                && netOutputAmount + feeAmount + protocolFeeAmount == expectedOutput
        );
    }

    receive() external payable {}
}
